import { Howl, Howler } from 'howler';

/* Game sounds (Howler.js). Files are generated by scripts/make-sounds.mjs. */

export type Effect = 'tick' | 'count' | 'go' | 'join' | 'timesup' | 'correct' | 'wrong' | 'reveal' | 'podium';
export type Music = 'lobby' | 'question';

const MUTE_KEY = 'tapblast_muted';
const base = `${import.meta.env.BASE_URL}sounds/`;
const howls = new Map<string, Howl>();
let currentMusic: Music | null = null;

function readMuted(): boolean {
  try {
    return localStorage.getItem(MUTE_KEY) === '1';
  } catch {
    return false;
  }
}

let muted = readMuted();
Howler.mute(muted);
const listeners = new Set<(muted: boolean) => void>();

function get(name: Effect | Music, music: boolean): Howl {
  let h = howls.get(name);
  if (!h) {
    h = new Howl({ src: [base + name + (music ? '.wav' : '.mp3')], loop: music, volume: music ? 0.35 : 0.8, html5: false });
    howls.set(name, h);
  }
  return h;
}

export const sound = {
  play(name: Effect) {
    get(name, false).play();
  },

  /** Starts a music loop (or stops music with null). Calling with the current loop is a no-op. */
  music(name: Music | null) {
    if (name === currentMusic) return;
    if (currentMusic) {
      const old = get(currentMusic, true);
      old.fade(old.volume(), 0, 250);
      setTimeout(() => old.stop(), 260);
    }
    currentMusic = name;
    if (name) {
      const h = get(name, true);
      h.volume(0.35);
      h.play();
    }
  },

  /** Loads files ahead of time so the first play isn't delayed. */
  preload(names: Effect[]) {
    names.forEach((n) => get(n, false));
  },

  isMuted: () => muted,

  setMuted(next: boolean) {
    muted = next;
    Howler.mute(next);
    try {
      localStorage.setItem(MUTE_KEY, next ? '1' : '0');
    } catch {
      /* private mode: setting just won't persist */
    }
    listeners.forEach((cb) => cb(next));
  },

  subscribe(cb: (muted: boolean) => void) {
    listeners.add(cb);
    return () => {
      listeners.delete(cb);
    };
  },
};
